"""Self-contained HTML renderer for the static knowledge dashboard."""
from __future__ import annotations

import html
import json


HTML = """<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>__TITLE__</title><style>
:root{--bg:#07111e;--card:#0f2034;--line:#294766;--text:#eaf3ff;--muted:#a4b7cc;--primary:__PRIMARY__;--accent:__ACCENT__}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:32px}.tag{color:var(--primary);font:11px ui-monospace,monospace;text-transform:uppercase;letter-spacing:.1em}h1{font-size:34px;margin:7px 0}.intro,.meta{color:var(--muted);line-height:1.55}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:26px 0}.card{background:var(--card);border:1px solid var(--line);border-radius:12px}.kpi{padding:17px}.kpi b{display:block;font-size:27px;margin-top:6px;color:var(--primary)}.grid{display:grid;grid-template-columns:1fr 370px;gap:16px}.toolbar{padding:14px;display:flex;gap:9px;border-bottom:1px solid var(--line)}input,button{background:#09192a;border:1px solid var(--line);border-radius:7px;color:var(--text);padding:9px}input{width:100%}button{cursor:pointer}button.on{border-color:var(--primary);color:var(--primary)}table{border-collapse:collapse;width:100%}th,td{padding:12px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--muted);font-size:10px;text-transform:uppercase}tr{cursor:pointer}tr:hover{background:#182f4a}.ready{color:var(--primary)}.attention{color:#ffc970}aside{padding:18px;min-height:420px}aside p,aside li{color:var(--muted);line-height:1.55}.stats{display:grid;grid-template-columns:1fr 1fr;gap:8px}.stat{padding:10px;background:#09192a;border-radius:7px;color:var(--muted)}.stat b{display:block;font-size:18px;color:var(--primary)}footer{margin-top:18px;color:var(--muted)}@media(max-width:800px){main{padding:18px}.kpis{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}</style></head><body><main><div class='tag'>__TAGLINE__</div><h1>__PRODUCT__</h1><p class='intro'>__INTRO__</p><section class='kpis' id='kpis'></section><p class='meta' id='meta'></p><section class='grid'><section class='card'><div class='toolbar'><input id='find' placeholder='Filter assets, formats, classes, predicates'><button class='on' data-filter='all'>All</button><button data-filter='Ontology'>Ontologies</button></div><table><thead><tr><th>Asset</th><th>Format</th><th>Profile</th></tr></thead><tbody id='rows'></tbody></table></section><aside class='card' id='detail'><p>Select an ontology to inspect its schema profile.</p></aside></section><footer>__FOOTER__</footer></main><script>const I=__DATA__;let filter='all';const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const n=x=>new Intl.NumberFormat().format(x);function rows(){let q=find.value.toLowerCase(),list=I.assets.filter(x=>(filter==='all'||x.kind===filter)&&JSON.stringify(x).toLowerCase().includes(q));document.querySelector('#rows').innerHTML=list.map(x=>{let p=x.profile;return `<tr onclick="showDetail('${x.id}')"><td><b>${e(x.relativePath)}</b><br><small>${e(x.kind)}</small></td><td>${e(x.extension)}</td><td>${p?`<span class='${p.status}'>${p.status}</span><br><small>${n(p.triples)} triples · ${p.classes} classes</small>`:'—'}</td></tr>`}).join('')||'<tr><td colspan=3>No matching assets</td></tr>'}function showDetail(id){let x=I.assets.find(v=>v.id===id),p=x.profile;if(!p){document.querySelector('#detail').innerHTML='<p>Non-semantic knowledge asset.</p>';return}document.querySelector('#detail').innerHTML=`<div class='tag'>${e(x.extension)} ontology</div><h2>${e(x.relativePath)}</h2><div class='stats'>${[['Triples',p.triples],['Classes',p.classes],['Object properties',p.objectProperties],['Datatype properties',p.datatypeProperties]].map(a=>`<div class='stat'><b>${n(a[1])}</b>${a[0]}</div>`).join('')}</div><h3>Classes</h3><p>${p.classSample.map(e).join(' · ')||'No explicit classes found.'}</p><h3>Predicates</h3><p>${p.predicateSample.map(e).join(' · ')||'—'}</p><h3>Namespaces</h3><ul>${p.namespaces.map(v=>`<li>${e(v)}</li>`).join('')||'<li>—</li>'}</ul>${p.error?`<p class='attention'>${e(p.error)}</p>`:''}`};const find=document.querySelector('#find');find.oninput=rows;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('on',x===b));rows()});document.querySelector('#kpis').innerHTML=[['Knowledge assets',I.summary.assets],['Ontologies',I.summary.ontologies],['RDF triples',I.summary.triples],['Classes',I.summary.classes]].map(a=>`<div class='card kpi'><small>${a[0]}</small><b>${n(a[1])}</b></div>`).join('');document.querySelector('#meta').textContent=`Scanned ${I.roots.join(' · ')} | ${Object.entries(I.summary.formats).map(a=>a[0]+' ('+a[1]+')').join(', ')}`;rows();</script></body></html>"""


def render_dashboard(inventory: dict, title: str, *, product_name: str = "Knowledge Sandbox", product_tagline: str = "Knowledge Management · local directory scan", introduction: str = "A portable knowledge inventory for configured folders.", primary_color: str = "#63e6be", accent_color: str = "#b39cff", footer_html: str = "") -> str:
    replacements = {"__TITLE__": html.escape(title), "__PRODUCT__": html.escape(product_name), "__TAGLINE__": html.escape(product_tagline), "__INTRO__": html.escape(introduction), "__PRIMARY__": html.escape(primary_color), "__ACCENT__": html.escape(accent_color), "__FOOTER__": footer_html, "__DATA__": json.dumps(inventory, ensure_ascii=False).replace("</script", "<\\/script")}
    result = HTML
    for needle, value in replacements.items():
        result = result.replace(needle, value)
    return result
